class FooBad {
    OutputStream bad(Path path) throws IOException {
        return Files.newOutputStream(path); // bad 2x - 'Files' is an AmbiguousName and 'path' is a var of unknown type
    }
}

import java.nio.file.*;
class FooGood {
    OutputStream good(Path path) throws IOException {
        return Files.newOutputStream(path); // 'Files' known because of import, and bytecode on classpath
    }
}

@Service
@Slf4j
public class MyProducerBad1 {
    public void delete(String idStr) {
        log.debug("delete --> {}", idStr); // bad: no import
    }
}

import lombok.extern.slf4j.Slf4j;
@Service
public class MyProducerBad2 {
    public void delete(String idStr) {
        log.debug("delete --> {}", idStr); // bad: no @Slf4j
    }
}

import lombok.extern.slf4j.Slf4j;
@Service
@Slf4j
public class MyProducerGood {
    public void delete(String idStr) {
        log.debug("delete --> {}", idStr); // good:  import and @Slf4j
    }
}

class Foo {
    int bar() {
        int count = 0;
        return count += 5;
    }
}

class Issue544_lambda {
    public TomcatServletWebServerFactory webServerFactory() {
        TomcatServletWebServerFactory factory = new TomcatServletWebServerFactory();
        factory.addConnectorCustomizers(connector -> connector.setProperty("prop", "test")); // <- false positive on 'connector'
        return factory;
    }
}

class TomcatServletWebServerFactory {
    void addConnectionCustomizers(TomcatConnectorCustomizer... connector) {}
}

@FunctionalInterface
public interface TomcatConnectorCustomizer {
    void customize(Connector connector);
}
public class Connector {
    public void setProperty(String name, String val) {}
}

import lombok.extern.slf4j.Slf4j;
@Slf4j
public class EnvironmentLogService {
    public void init() {
        Environment.logEnv("server environment:", log);
    }
}
class Environment {
    void logEnv(String text, Log log) {}
}
